import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();
        long numerator = 0;
        long denominator = 1;

        for (long i = 1; i <= n; ++i) {
            long lower = (i * x) / y;
            long upper = lower + 1;

            // Lambda equivalent as a method
            class FractionUpdater {
                void updateFraction(long candidate, long index) {
                    long diff1 = Math.abs((denominator * y) * ((x * index) - (y * candidate)));
                    long diff2 = Math.abs((y * index) * ((denominator * x) - (numerator * y)));
                    if (diff1 < diff2 || (diff1 == diff2 && index < denominator)) {
                        denominator = index;
                        numerator = candidate;
                    }
                }
            }

            FractionUpdater updater = new FractionUpdater();
            updater.updateFraction(lower, i);
            updater.updateFraction(upper, i);
        }

        System.out.println(numerator + "/" + denominator);
        scanner.close();
    }
}

